package org.sleepwell.app;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.speech.RecognizerIntent;import android.view.*;import android.widget.*;import java.time.*;import java.time.format.*;import java.util.*;import org.json.*;
/** One reviewed time proposal. No scheduling, alarm storage or app microphone capture. */
public final class RelativeAlarmTimeActivity extends Activity {
 static final int REQUEST=686,SPEECH=688;private Alarm alarm;private String request,error="",heard="";private int minutes=30;private RelativeAlarmTime proposal;private Dialog picker;private Bundle restoredPicker;private boolean speechPending;private long speechStarted;private ArrayList<String> speechResults;private float[] speechScores;
 static Intent edit(Activity owner,Alarm alarm,String request){return RecordUi.intent(owner,RelativeAlarmTimeActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("request",request);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);try{request=getIntent().getStringExtra("request");if(request==null||!UUID.fromString(request).toString().equals(request))throw new IllegalArgumentException();alarm=Alarm.read(new JSONObject(getIntent().getStringExtra("alarm")));if(saved!=null){minutes=saved.getInt("minutes",30);if(minutes<1||minutes>1440)throw new IllegalArgumentException();error=saved.getString("error","");heard=saved.getString("heard","");speechPending=saved.getBoolean("speechPending");speechStarted=saved.getLong("speechStarted");speechResults=saved.getStringArrayList("speechResults");speechScores=saved.getFloatArray("speechScores");restoredPicker=saved.getBundle("durationPicker");if(saved.containsKey("proposalWall"))proposal=new RelativeAlarmTime(minutes,saved.getLong("proposalWall"),saved.getLong("proposalElapsed"),ZoneId.of(saved.getString("proposalZone")));}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();if(restoredPicker!=null){Bundle restore=restoredPicker;restoredPicker=null;openDuration();if(picker instanceof SleepPicker.StateDialog)picker.onRestoreInstanceState(restore);}}catch(Exception invalid){finish();}}
 private void choose(int value){minutes=value;proposal=null;error="";heard="";render();}
 private void openDuration(){if(picker!=null)picker.dismiss();picker=SleepPicker.duration(this,"Relative duration",minutes,1,1440,this::choose);}
 private Intent speechIntent(){return new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"en-US").putExtra(RecognizerIntent.EXTRA_PREFER_OFFLINE,true).putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,3).putExtra(RecognizerIntent.EXTRA_PROMPT,"Say: in 2 hours 15 minutes");}
 private ResolveInfo speechProvider(){try{ResolveInfo found=getPackageManager().resolveActivity(speechIntent(),PackageManager.MATCH_DEFAULT_ONLY);return found!=null&&found.activityInfo!=null&&found.activityInfo.exported&&found.activityInfo.enabled&&found.activityInfo.applicationInfo.enabled?found:null;}catch(RuntimeException unavailable){return null;}}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Relative alarm time",this::finish);Design.space(body,16);if(!RelativeAlarmTime.allowed(alarm)){Design.text(body,"Use a one-time clock alarm",24,600,Design.INK);Design.text(body,"Turn repeat days off and choose Clock time before using relative entry. Naps use their own timer.",15,400,Design.MUTED);Design.fixedAction(body,"Return to alarm",this::finish);return;}Design.text(body,"In hours and minutes",25,600,Design.INK);Design.space(body,12);Design.item(body,"clock","Duration",PlanActivity.duration(minutes),this::openDuration);Design.line(body);Design.text(body,"A fixed one-time date and clock time are copied into your draft. The duration starts when you tap Review time.",13,400,Design.MUTED);Design.space(body,12);Design.button(body,"Review time",true,this::review);if(proposal!=null){Design.space(body,18);LinearLayout panel=Design.col(this);Design.pad(panel,18,20);panel.setBackground(Design.shape(this,Design.SOFT,18));Design.text(panel,Design.clock(this,proposal.local.getHour()*60+proposal.local.getMinute()),38,600,Design.BROWN).setContentDescription("Proposed relative alarm time");Design.text(panel,proposal.local.toLocalDate().format(DateTimeFormatter.ofLocalizedDate(FormatStyle.FULL)),15,500,Design.INK);Design.text(panel,proposal.zone.getId()+" · "+proposal.local.getOffset(),13,400,Design.MUTED);Design.space(panel,10);Design.text(panel,proposal.rounding(),13,400,Design.MUTED);if(proposal.clockChanges())Design.text(panel,"A clock change occurs during this interval. The calculation uses elapsed duration; the local clock difference may vary.",13,500,Design.BROWN);body.addView(panel);}Design.space(body,24);Design.text(body,"Optional speech entry",19,600,Design.INK);ResolveInfo provider=speechProvider();String providerName=provider==null?"No installed speech entry provider":provider.loadLabel(getPackageManager()).toString();Design.text(body,providerName,13,500,Design.MUTED);Design.space(body,6);Design.text(body,"Opens another app to recognize a short English relative duration. Offline recognition is requested, but that app may use its network service. Review a recognized candidate before using it.",12,400,Design.MUTED);Button speak=Design.button(body,"Open speech entry",false,this::speak);RecordUi.enabled(speak,provider!=null&&!speechPending);if(speechPending)Design.text(body,"Waiting for speech entry. Returning or cancelling does not change the alarm.",12,400,Design.MUTED);if(speechResults!=null){try{for(RelativeTimeSpeech.Candidate candidate:RelativeTimeSpeech.candidates(speechResults,speechScores)){Design.text(body,"Heard: "+candidate.heard+" · "+candidate.confidence,12,400,Design.MUTED);Design.button(body,"Choose "+PlanActivity.duration(candidate.minutes),false,()->{heard=candidate.heard;speechResults=null;speechScores=null;minutes=candidate.minutes;proposal=null;error="";render();});}}catch(IllegalArgumentException unsupported){error=unsupported.getMessage();}}if(!heard.isEmpty())Design.text(body,"Selected speech text: "+heard+". Review the numeric duration above.",12,400,Design.MUTED);LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty()){TextView issue=Design.text(footer,error,13,500,0xffa93919);issue.setContentDescription("Relative time entry error");issue.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}Design.text(footer,"Use this time updates the draft only. Save alarm to keep it.",12,400,Design.MUTED);Design.button(footer,"Use this time",true,this::use).setEnabled(proposal!=null);Design.button(footer,"Cancel",false,this::finish);}
 private void review(){try{if(!RelativeAlarmTime.allowed(alarm))throw new IllegalArgumentException("Choose a one-time clock alarm first.");proposal=new RelativeAlarmTime(minutes,System.currentTimeMillis(),SystemClock.elapsedRealtime(),ZoneId.systemDefault());error="";}catch(IllegalArgumentException invalid){proposal=null;error=invalid.getMessage();}render();}
 private void use(){try{if(!hasWindowFocus()||proposal==null||!RelativeAlarmTime.allowed(alarm))throw new IllegalArgumentException("Review a new time before using it.");proposal.check(System.currentTimeMillis(),SystemClock.elapsedRealtime(),ZoneId.systemDefault());setResult(RESULT_OK,new Intent().putExtra("request",request).putExtra("draft",RelativeAlarmTime.identity(alarm)).putExtra("duration",minutes).putExtra("wall",proposal.wall).putExtra("elapsed",proposal.elapsed).putExtra("target",proposal.target).putExtra("zone",proposal.zone.getId()));finish();}catch(IllegalArgumentException invalid){error=invalid.getMessage();render();}}
 private void speak(){if(speechPending||!hasWindowFocus())return;ResolveInfo provider=speechProvider();if(provider==null){error="Speech entry is not installed or is unavailable. Choose a duration instead.";render();return;}try{speechPending=true;speechStarted=SystemClock.elapsedRealtime();error="";Intent intent=speechIntent().setComponent(new ComponentName(provider.activityInfo.packageName,provider.activityInfo.name));startActivityForResult(intent,SPEECH);}catch(RuntimeException unavailable){speechPending=false;error="Speech entry could not open. Choose a duration instead.";render();}}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code!=SPEECH)return;boolean owned=speechPending&&SystemClock.elapsedRealtime()>=speechStarted&&SystemClock.elapsedRealtime()-speechStarted<=180000;speechPending=false;if(!owned){error="Speech entry expired. Choose a duration or try again.";render();return;}if(result!=RESULT_OK||data==null){error="Speech entry cancelled. Your selected duration is unchanged.";render();return;}try{ArrayList<String> results=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(results==null||results.isEmpty())throw new IllegalArgumentException("No recognized text was returned.");proposal=null;speechResults=new ArrayList<>();for(int n=0;n<Math.min(3,results.size());n++){String text=results.get(n);if(text==null||text.length()>120)throw new IllegalArgumentException("Speech text is too long. Use a short relative duration.");speechResults.add(text);}float[] scores=data.getFloatArrayExtra(RecognizerIntent.EXTRA_CONFIDENCE_SCORES);speechScores=scores!=null&&scores.length==results.size()?Arrays.copyOf(scores,speechResults.size()):null;RelativeTimeSpeech.candidates(speechResults,speechScores);error="Choose the recognized duration, then Review time.";}catch(RuntimeException invalid){speechResults=null;speechScores=null;error=invalid.getMessage()==null?"Speech results could not be read. Choose a duration instead.":invalid.getMessage();}render();}
 @Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);saved.putInt("minutes",minutes);saved.putString("error",error);saved.putString("heard",heard);saved.putBoolean("speechPending",speechPending);saved.putLong("speechStarted",speechStarted);if(speechResults!=null)saved.putStringArrayList("speechResults",speechResults);if(speechScores!=null)saved.putFloatArray("speechScores",speechScores);if(proposal!=null){saved.putLong("proposalWall",proposal.wall);saved.putLong("proposalElapsed",proposal.elapsed);saved.putString("proposalZone",proposal.zone.getId());}if(picker instanceof SleepPicker.StateDialog&&picker.isShowing())saved.putBundle("durationPicker",picker.onSaveInstanceState());}
 @Override protected void onDestroy(){if(picker!=null)picker.dismiss();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
